#!/usr/bin/env -S uv run --script
# Synced from bootstrap: repo/tools/docker/tasks/setup-external-update.py. Do not edit this file.
# The next sync writes it again, and each change in this file is lost.
# /// script
# requires-python = ">=3.14"
# dependencies = []
# ///
# MISE description="Update the local services: stop, pull, start (at most once a week)"
# MISE hide=true
# MISE tools={uv="latest", python="3.14"}
# USAGE flag "-f --force" help="update even if the last update was less than a week ago"

import os
import subprocess
import sys
import time

sys.dont_write_bytecode = True
sys.path.insert(0, f"{os.environ['MISE_PROJECT_ROOT']}/.config/mise/tasks/_scripts")
import helpers  # noqa: E402

# Local services are for development only.
if os.environ.get("MISE_ENV", "") != "dev":
  sys.exit(0)

stamp_file = f"{os.environ.get('TMPDIR') or '/tmp'}/mise-external-update-{os.environ.get('REPO_NAME') or 'repo'}.stamp"
ONE_WEEK_SECONDS = 7 * 24 * 60 * 60

if os.environ.get("usage_force") == "true":
  try:
    os.remove(stamp_file)
  except FileNotFoundError:
    pass
elif os.path.isfile(stamp_file):
  elapsed = int(time.time()) - int(os.stat(stamp_file).st_mtime)
  if elapsed < ONE_WEEK_SECONDS:
    helpers.print_info("The last update was less than a week ago. Use --force to update now.")
    sys.exit(0)

for task in ("setup:external:stop", "setup:external:pull", "setup:external:start"):
  result = subprocess.run(["mise", "run", task], check=False)
  if result.returncode != 0:
    sys.exit(result.returncode)

with open(stamp_file, "a"):
  os.utime(stamp_file)
helpers.print_success("Local services updated")
